// Unit tests for pipeline/parser.js
// Run with: node --test pipeline/parser.test.js

const { describe, it } = require("node:test");
const assert = require("node:assert/strict");
const { extractNumber, getKeywordTier } = require("./parser");

// ══════════════════════════════════════════════════════════════════════════
// extractNumber
// ══════════════════════════════════════════════════════════════════════════

describe("extractNumber", () => {
  describe("plain numbers", () => {
    it("parses a simple decimal", () => { assert.equal(extractNumber("93.42"), 93.42); });
    it("parses an integer", () => { assert.equal(extractNumber("100"), 100); });
    it("returns null for zero", () => { assert.equal(extractNumber("0"), null); });
    it("returns null for value above sanity ceiling (>9,999,999)", () => { assert.equal(extractNumber("10000000"), null); });
    it("returns null for empty string", () => { assert.equal(extractNumber(""), null); });
    it("returns null for pure text with no digits", () => { assert.equal(extractNumber("total"), null); });
  });

  describe("currency prefix stripping", () => {
    it("strips EGP prefix", () => { assert.equal(extractNumber("EGP 545.99"), 545.99); });
    it("strips ٤GP (Arabic OCR variant of EGP)", () => { assert.equal(extractNumber("٤GP 140.00"), 140); });
    it("strips dollar sign", () => { assert.equal(extractNumber("$93.42"), 93.42); });
    it("strips USD suffix", () => { assert.equal(extractNumber("93.42 USD"), 93.42); });
    it("strips DL: prefix (Syrian pound)", () => { assert.equal(extractNumber("DL: 498.000"), 498); });
    it("strips LE prefix", () => { assert.equal(extractNumber("LE 200.00"), 200); });
    it("strips /month suffix", () => { assert.equal(extractNumber("99.99/month"), 99.99); });
    it("strips trailing colon", () => { assert.equal(extractNumber("54.00:"), 54); });
  });

  describe("OCR error corrections", () => {
    it("corrects E6P → EGP and strips it", () => { assert.equal(extractNumber("E6P 560.00"), 560); });
    it("corrects E1P → EGP and strips it", () => { assert.equal(extractNumber("E1P 200.00"), 200); });
    it("strips bracket annotations e.g. 'Total [24]'", () => { assert.equal(extractNumber("24 [24]"), 24); });
  });

  describe("Arabic-Indic numerals", () => {
    it("converts ٥٥,٩٩ → 55.99", () => { assert.equal(extractNumber("٥٥,٩٩"), 55.99); });
    it("converts a fully Arabic-Indic integer (١٢٣ = 123)", () => { assert.equal(extractNumber("١٢٣"), 123); });
  });

  describe("European number formats", () => {
    it("handles period-as-thousands, comma-as-decimal (1.051,00)", () => { assert.equal(extractNumber("1.051,00"), 1051); });
    it("handles double-dot thousands (2.215.25 → 2215.25)", () => { assert.equal(extractNumber("2.215.25"), 2215.25); });
    it("handles comma-only decimal (55,99 → 55.99)", () => { assert.equal(extractNumber("55,99"), 55.99); });
    it("handles multiple commas — last is decimal (11,599,00)", () => { assert.equal(extractNumber("11,599,00"), 11599); });
    it("handles comma-as-thousands, dot-as-decimal (1,051.00)", () => { assert.equal(extractNumber("1,051.00"), 1051); });
  });

  describe("whitespace in numbers", () => {
    it("removes whitespace (11, 599, 00 → 11599)", () => { assert.equal(extractNumber("11, 599, 00"), 11599); });
    it("treats trailing 2-digit group after space as decimal (93 42 → 93.42)", () => { assert.equal(extractNumber("93 42"), 93.42); });
  });

  describe("leading-dot OCR patterns", () => {
    it("handles .XX. XX pattern (.53. 28 → 53.28)", () => { assert.equal(extractNumber(".53. 28"), 53.28); });
    it("strips a plain leading dot (.99 → 99)", () => { assert.equal(extractNumber(".99"), 99); });
  });
});

