describe("getKeywordTier", () => {
  describe("tier 1 keywords", () => {
    it("returns 1 for 'grand total'", () => { assert.equal(getKeywordTier("grand total"), 1); });
    it("returns 1 for 'total due'", () => { assert.equal(getKeywordTier("total due"), 1); });
    it("returns 1 for 'amount due'", () => { assert.equal(getKeywordTier("amount due"), 1); });
    it("returns 1 for 'invoice total'", () => { assert.equal(getKeywordTier("invoice total"), 1); });
    it("returns 1 for 'total' alone (French receipts)", () => { assert.equal(getKeywordTier("total"), 1); });
    it("returns 1 for Arabic الإجمالي", () => { assert.equal(getKeywordTier("الإجمالي"), 1); });
    it("returns 1 for Hungarian 'összesen'", () => { assert.equal(getKeywordTier("összesen"), 1); });
    it("is case-insensitive (GRAND TOTAL)", () => { assert.equal(getKeywordTier("GRAND TOTAL"), 1); });
    it("strips trailing colon (Total:)", () => { assert.equal(getKeywordTier("Total:"), 1); });
  });

  describe("tier 1 via OCR character correction", () => {
    it("corrects T0TAL → TOTAL", () => { assert.equal(getKeywordTier("T0TAL"), 1); });
    it("corrects GR4ND T0TAL → GRAND TOTAL", () => { assert.equal(getKeywordTier("GR4ND T0TAL"), 1); });
    it("corrects 1NV0ICE T0TAL → INVOICE TOTAL", () => { assert.equal(getKeywordTier("1NV0ICE T0TAL"), 1); });
    it("corrects F1NAL T0TAL → FINAL TOTAL", () => { assert.equal(getKeywordTier("F1NAL T0TAL"), 1); });
  });

  describe("tier 2 keywords", () => {
    it("returns 2 for 'amount'", () => { assert.equal(getKeywordTier("amount"), 2); });
    it("returns 2 for 'usd'", () => { assert.equal(getKeywordTier("usd"), 2); });
    it("returns 2 for 'EGP'", () => { assert.equal(getKeywordTier("EGP"), 2); });
  });

  describe("blacklisted keywords → 0", () => {
    it("returns 0 for 'subtotal'", () => { assert.equal(getKeywordTier("subtotal"), 0); });
    it("returns 0 for 'vat'", () => { assert.equal(getKeywordTier("vat"), 0); });
    it("returns 0 for 'tax'", () => { assert.equal(getKeywordTier("tax"), 0); });
    it("returns 0 for 'discount'", () => { assert.equal(getKeywordTier("discount"), 0); });
    it("returns 0 for 'delivery fee'", () => { assert.equal(getKeywordTier("delivery fee"), 0); });
    it("returns 0 for 'Total Taxes $6.92' (35.webp)", () => { assert.equal(getKeywordTier("Total Taxes $6.92"), 0); });
    it("returns 0 for 'Total no. of items 6' (42.jpg)", () => { assert.equal(getKeywordTier("Total no. of items 6"), 0); });
    it("returns 0 for 'change'", () => { assert.equal(getKeywordTier("change"), 0); });
    it("blacklist takes priority over tier 1 match", () => { assert.equal(getKeywordTier("items total"), 0); });
  });

  describe("no keyword match → -1", () => {
    it("returns -1 for an unrelated word", () => { assert.equal(getKeywordTier("chicken sandwich"), -1); });
    it("returns -1 for a plain number string", () => { assert.equal(getKeywordTier("93.42"), -1); });
    it("returns -1 for empty string", () => { assert.equal(getKeywordTier(""), -1); });
  });
});
